/// How safe a rule's items are to remove. See `docs/RULE_CATALOG.md` §1.
public enum Tier: String, Sendable, Codable, Hashable {
    /// Regenerated by its owner. Selected by default.
    case safe
    /// Probably safe, but may hold the user's only copy. Never selected by default.
    case review
    /// Real space use that only macOS or the owning app can reduce. Has no delete action.
    case info
}

/// The access a rule needs to read or change its roots.
public enum Access: String, Sendable, Codable, Hashable {
    /// Readable as the logged-in user.
    case user
    /// Needs Full Disk Access.
    case fda
    /// Needs root. Info rows only in v1.
    case root
}

/// Sidebar group a rule belongs to.
public enum Category: String, Sendable, Codable, Hashable, CaseIterable {
    case caches
    case logs
    case trash
    case browsers
    case apps
    case developer
    case mail
    case ios
    case installers
    case system
}
